/* N-Line: the menu pane's layout, shared by the Tryton page (custom.js) and
 * the desk's Settings > Menu Layout screen (menulayout.js).
 *
 * A user's layout is saved on their user (res.user nline_menu_prefs, JSON):
 *   {hidden: [menu id], scheme: 'interior', style: 'mixed',
 *    icons: {menu id: symbol}, colors: {menu id: '#hex'}}
 * The icons are drawn here from the symbols of menuicons.js (generated by
 * nline_desk/tools/gen_icons.py) in the scheme's colours.
 */
(function (global) {
    'use strict';

    /* The tabs across the top and the top menus each shows (Home in all);
     * a top menu not listed here shows under Admin */
    var CATEGORIES = [
        ['Inventory/Engineering', ['Inventory', 'Engineering', 'Products',
            'Inventory & Stock', 'Productions']],
        ['Quotation/Sales', ['Estimating', 'Sales', 'Customers']],
        ['RFQ/Purchasing', ['Purchasing', 'Vendors', 'Purchases']],
        ['Shopfloor', ['Shopfloor', 'Planning']],
        ['Accounting', ['Accounting', 'Company', 'Banking', 'Financial',
            'Executive Information', 'Currencies', 'Banks']],
        ['Settings', ['My Settings', 'Common', 'Companies', 'Parties']],
        ['Admin', ['Administration', 'System Administration']]
    ];
    var ALWAYS = ['Home'];

    /* Colour schemes: 14 colours each, in the order the icons pick them */
    var SCHEMES = {
        interior: {name: 'Interior', note: 'sage, terracotta, clay, ochre',
            colors: ['#8a9a7b', '#c46a4a', '#b5835a', '#c9a04a', '#2f3e5c',
                '#6e8ca8', '#6b7046', '#6e4a5e', '#c98e86', '#6b4f3a',
                '#b08d57', '#3d3f42', '#4f6b5e', '#a65d57']},
        coastal: {name: 'Coastal', note: 'harbour blues, sand, driftwood',
            colors: ['#4f6d8a', '#c2a878', '#8fb3c9', '#2e4a62', '#d9b38c',
                '#7d97a8', '#a68a64', '#5d7f99', '#b9c6cf', '#3b5b75',
                '#c9b28f', '#6e8796', '#8c7356', '#46627a']},
        earth: {name: 'Earth', note: 'olive, rust, walnut, moss',
            colors: ['#6b7046', '#a0522d', '#7b5e3b', '#8f7a3a', '#4e5b31',
                '#b5693f', '#5a4632', '#8a8d4f', '#9c6b4e', '#3f4a2a',
                '#c08a4a', '#6d5a45', '#7f6a2e', '#94563a']},
        slate: {name: 'Slate', note: 'navy and greys, quiet',
            colors: ['#2f3e5c', '#4a5568', '#5f6f86', '#3d3f42', '#6b7a90',
                '#2b3445', '#7a8597', '#46536a', '#565b63', '#38465e',
                '#677388', '#2f3a4a', '#58667c', '#40495a']},
        jewel: {name: 'Jewel', note: 'emerald, sapphire, ruby, amethyst',
            colors: ['#1f7a5a', '#2a4b9b', '#a3263c', '#6b3fa0', '#b8860b',
                '#16697a', '#8c2f5a', '#3c6e2f', '#4b3c9b', '#a0522d',
                '#205e8c', '#7a1f3d', '#5c4a9b', '#2f6b4f']},
        nline: {name: 'N-Line', note: 'navy and the logo orange',
            colors: ['#1f4e8c', '#e8650a', '#163a69', '#d9600a', '#3a6aa8',
                '#f2862e', '#24508f', '#b84f08', '#4a78b0', '#e07a2e',
                '#1a4170', '#c96012', '#5683bb', '#ef9348']}
    };
    var STYLES = {mixed: 'Mixed (each its own)', solid: 'Solid tiles',
        soft: 'Soft tiles', ring: 'Outlined'};

    function parse(text) {
        var prefs = {};
        try {
            prefs = text ? JSON.parse(text) : {};
        } catch (e) {
            prefs = {};
        }
        return {
            hidden: prefs.hidden || [],
            scheme: SCHEMES[prefs.scheme] ? prefs.scheme : 'interior',
            style: STYLES[prefs.style] ? prefs.style : 'mixed',
            icons: prefs.icons || {},
            colors: prefs.colors || {}
        };
    }

    function categoryOf(name) {
        for (var i = 0; i < CATEGORIES.length; i++) {
            if (CATEGORIES[i][1].indexOf(name) >= 0) {
                return CATEGORIES[i][0];
            }
        }
        return ALWAYS.indexOf(name) >= 0 ? null : 'Admin';
    }

    function tint(colour, amount) {
        var rgb = [1, 3, 5].map(function (i) {
            return parseInt(colour.substr(i, 2), 16);
        });
        return '#' + rgb.map(function (c) {
            return ('0' + Math.round(c + (255 - c) * amount).toString(16))
                .slice(-2);
        }).join('');
    }

    function data() {
        return global.NLineMenuIcons || {glyphs: {}, icons: {},
            styles: ['solid', 'soft', 'ring']};
    }

    /* The svg of a symbol in a colour and a tile style */
    function svg(glyph, colour, style) {
        var paths = data().glyphs[glyph] || data().glyphs.list || [];
        var tile, ink;
        if (style === 'solid') {
            tile = '<rect x="0.5" y="0.5" width="23" height="23" rx="6" ' +
                'fill="' + colour + '"/>';
            ink = '#ffffff';
        } else if (style === 'soft') {
            tile = '<rect x="0.5" y="0.5" width="23" height="23" rx="6" ' +
                'fill="' + tint(colour, 0.78) + '"/>';
            ink = colour;
        } else {
            tile = '<rect x="1.25" y="1.25" width="21.5" height="21.5" ' +
                'rx="6" fill="#ffffff" stroke="' + colour +
                '" stroke-width="1.5"/>';
            ink = colour;
        }
        return '<svg xmlns="http://www.w3.org/2000/svg" width="24" ' +
            'height="24" viewBox="0 0 24 24">' + tile +
            '<g transform="translate(4.2 4.2) scale(0.65)">' +
            paths.map(function (d) {
                return '<path fill="' + ink + '" d="' + d + '"/>';
            }).join('') + '</g></svg>';
    }

    /* A menu's look: {glyph, colour, style}; its own choices first, then
     * its generated icon's symbol in the scheme */
    function look(menu, prefs) {
        var base = data().icons[menu.icon] || null;
        var id = String(menu.id);
        var index = base ? base[1] : (menu.id * 5) % 14;
        var colours = SCHEMES[prefs.scheme].colors;
        var styles = data().styles || ['solid', 'soft', 'ring'];
        return {
            glyph: prefs.icons[id] || (base ? base[0] : null),
            colour: prefs.colors[id] || colours[index % colours.length],
            style: prefs.style === 'mixed' ? styles[base ? base[2] :
                menu.id % styles.length] : prefs.style,
            generated: Boolean(base)
        };
    }

    /* The icon of a menu as an image address; null: keep the server's (a
     * Tryton icon nobody changed) */
    function iconUrl(menu, prefs) {
        var l = look(menu, prefs);
        if (!l.glyph || (!l.generated && !prefs.icons[String(menu.id)] &&
                !prefs.colors[String(menu.id)])) {
            return null;
        }
        return 'data:image/svg+xml;charset=utf-8,' + encodeURIComponent(
            svg(l.glyph, l.colour, l.style));
    }

    global.NLineMenu = {CATEGORIES: CATEGORIES, ALWAYS: ALWAYS,
        SCHEMES: SCHEMES, STYLES: STYLES, parse: parse,
        categoryOf: categoryOf, look: look, svg: svg, iconUrl: iconUrl};
}(window));
